    },
    v003: {
      name: 'Premium Equipment Co',
      description: 'プレミアム機器・設備の専門業者。カスタマイズ対応が可能。',
      contact: 'info@premiumequip.com',
      phone: '+81-90-3456-7890',
      website: 'https://www.premiumequip.com',
      evaluationCount: 28,
      history: [
        { date: '2026-11-08', score: 88, evaluator: '山田太郎', comment: '安定した高品質。推奨ベンダー。' },
        { date: '2026-10-12', score: 87, evaluator: '鈴木次郎', comment: '対応が丁寧で信頼できる。' },
        { date: '2026-09-15', score: 85, evaluator: '田中花子', comment: '価格帯は高いが品質が良い。' }
      ]
    },
    v004: {
      name: 'Standard Distributor',
      description: '標準的な部品・消耗品を供給。コスト削減重視。',
      contact: 'support@standarddist.com',
      phone: '+81-90-4567-8901',
      website: 'https://www.standarddist.com',
      evaluationCount: 42,
      history: [
        { date: '2026-11-07', score: 65, evaluator: '山田太郎', comment: '納期遅延が頻発。改善計画の提出要求。' },
        { date: '2026-10-10', score: 68, evaluator: '鈴木次郎', comment: '応答が遅い。追跡困難。' },
