        { date: '2026-09-14', score: 83, evaluator: '田中花子', comment: '価格は中程度。納期は確実。' }
      ]
    }
  };

  let currentVendorId = null;
  let currentMonth = 11;

  vendorRows.forEach(row => {
    row.addEventListener('click', function() {
      vendorRows.forEach(r => r.classList.remove('active'));
      this.classList.add('active');
      currentVendorId = this.getAttribute('data-vendor-id');
      updateDetailPanel(currentVendorId);
      updateHistoryList(currentVendorId, currentMonth);
    });
  });

  function updateDetailPanel(vendorId) {
    const vendor = vendorData[vendorId];
    if (!vendor) return;

    detailTitle.textContent = vendor.name;
    detailContent.innerHTML = `
      <div class="detail-row">
        <div class="detail-label">説明</div>
        <div class="detail-value">${vendor.description}</div>
      </div>
      <div class="detail-row">
        <div class="detail-label">メールアドレス</div>
        <div class="detail-value"><a href="mailto:${vendor.contact}" class="detail-link">${vendor.contact}</a></div>
      </div>
      <div class="detail-row">
        <div class="detail-label">電話番号</div>
        <div class="detail-value"><a href="tel:${vendor.phone}" class="detail-link">${vendor.phone}</a></div>
      </div>
      <div class="detail-row">
        <div class="detail-label">ウェブサイト</div>
        <div class="detail-value"><a href="${vendor.website}" class="detail-link" target="_blank">${vendor.website}</a></div>
      </div>
      <div class="detail-row">
        <div class="detail-label">評価件数</div>
        <div class="detail-value">${vendor.evaluationCount}件</div>
      </div>
    `;
  }

  function updateHistoryList(vendorId, month) {
    const vendor = vendorData[vendorId];
    if (!vendor) return;

    const filtered = vendor.history.filter(h => {
      const hMonth = new Date(h.date).getMonth() + 1;
      return hMonth === month;
    });

    if (filtered.length === 0) {
      historyList.innerHTML = `<div class="empty-state">${month}月の評価履歴はありません</div>`;
      return;
    }

    historyList.innerHTML = filtered.map(h => `
      <div class="history-item">
        <div class="history-date">${h.date}</div>
        <div class="history-score">スコア: ${h.score}</div>
        <div class="history-comment">評価者: ${h.evaluator}</div>
        <div class="history-comment">コメント: ${h.comment}</div>
      </div>
    `).join('');
  }

  historyTabs.forEach(tab => {
    tab.addEventListener('click', function() {
      historyTabs.forEach(t => t.classList.remove('active'));
      this.classList.add('active');
      currentMonth = parseInt(this.getAttribute('data-month'));
      if (currentVendorId) {
        updateHistoryList(currentVendorId, currentMonth);
      }
    });
  });

  searchButton.addEventListener('click', function() {
    const keyword = searchInput.value.trim();
    if (keyword) {
      alert(`「${keyword}」の検索を実行: フルシステムでは検索結果一覧を表示します`);
    }
  });

  compareButton.addEventListener('click', function() {
    alert('複数ベンダー比較: フルシステムではモーダルで比較表を表示します');
  });

  alertItems.forEach(alert => {
    alert.addEventListener('click', function() {
      alert('アラート詳細: フルシステムではツールチップまたは詳細ペインを表示します');
    });
  });
}
